// Generates supabase/seed.sql and supabase/setup.sql (schema + seed) from src/lib/defaults.js.
// Run: npm run build:sql
import { readFileSync, writeFileSync } from "node:fs";
import { defaultCollections, defaultContent } from "../src/lib/defaults.js";

const lit = v => `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;
const out = [
  "-- =====================================================================",
  "--  Curava template — demo content (generated by scripts/build-sql.mjs)",
  "--  Only fills empty tables, so it never overwrites your edits.",
  "-- =====================================================================",
  "",
  "-- Page sections",
];

for (const [key, data] of Object.entries(defaultContent)) {
  out.push(`insert into public.site_content (key, data) values ('${key}', ${lit(data)}) on conflict (key) do nothing;`);
}

for (const [table, rows] of Object.entries(defaultCollections)) {
  const cols = Object.keys(rows[0]).filter(c => c !== "id");
  const payload = rows.map(({ id, ...r }) => r);
  out.push("", `-- ${table}`);
  out.push(
    `insert into public.${table} (${cols.join(", ")})\n` +
    `select ${cols.join(", ")} from jsonb_populate_recordset(null::public.${table}, ${lit(payload)})\n` +
    `where not exists (select 1 from public.${table});`
  );
}

const seed = out.join("\n") + "\n";
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), seed);
const schema = readFileSync(new URL("../supabase/schema.sql", import.meta.url), "utf8");
writeFileSync(
  new URL("../supabase/setup.sql", import.meta.url),
  "-- ONE-CLICK SETUP: schema + demo content. Paste everything into Supabase → SQL Editor → Run.\n\n" + schema + "\n\n" + seed
);
console.log("Wrote supabase/seed.sql and supabase/setup.sql");
